"""Reader-oriented result and handoff, without build narration."""
from dental_release.paths import expand as _release_expand
import json, datetime
from pathlib import Path
from contact import P, sha, write, state

def run():
    import csv
    with (P / 'raw/TOOTH_PAIR_MAP.csv').open() as f:
        exported = list(csv.DictReader(f))
    tight = [p for p in exported if p['enclosure_round'] == 'R4']
    maximum_width = max((float(p['minimum_enclosure_upper_mm']) - float(p['minimum_enclosure_lower_mm']) for p in tight))
    assert len(exported) == 38280 and len(tight) == 440 and (maximum_width <= 0.005 + 1e-09)
    write(P / 'raw/EXPORT_CHECK.json', dict(passed=True, rows=len(exported), refined_R4_rows=len(tight), maximum_refined_width_mm=maximum_width, remaining_rows_model='R3 conservative bound'))
    r = json.load(open(P / 'results.json'))
    rd = r['rounds']
    r5 = rd['R5']
    r6 = rd['R6']
    t = r['toothwise_crossbite']
    cost = r['costs']
    field = rd['R2']['fields']
    old = r5['test_report_disagreement_original']
    new = r5['test_report_disagreement_corrected']
    allnew = r5['all_cohort_disagreement_corrected']
    text = _release_expand("# Tandvis gapkarta mot klinikerns bettbeskrivning\n\nRun `./run_all.sh` from this catalogue. [Figur](figures/contact_report_demo.png), [gapintyg](figures/certificate_width.png), [CSV](raw/TOOTH_PAIR_MAP.csv)An existing case can be read with: `python3 code/demo_case.py --case @DENTAL_CASE_ID@`; egna STL-par med X11-labels are supported via `--upper --lower --segmentation`.\n\nThe idea: keep dental identity, opposite surface and non-contact geometry in the same registered scanning pairs. Continuous gaps get source triangles and mathematical intervals; projected proximity patches get area and position. The opposite point candidates are retained when contact is missing. The clinician's existing text is compared as a separate observation, with negation and anatomic region preserved.\n\nFacit: [Bite2Text authors' dataset](https://ditto.ing.unimore.it/bite2text/), lokal `Bite2Text.zip::*/reports_ios_en/*.txt`, 1 494 readable structured reports. SHA256 follows each comparison. The text measures categories and named corsbet teeth, **not gap, area or point coordinates**Mathematical gapfacit is affee minimum over projected triangle intersection, with precise rational witnesses and independent full tooth pairs controls. [Eberly primary derivation](https://www.geometrictools.com/Documentation/MethodOfSeparatingAxes.pdf), §2–3, indicates the linear projection minimum over the corners of convex polygons; here this applies to our affinity gap. It is a derived application for rounded mesh, no empirical contact validation. EXTERNAL_REFERENTS.json is a metadata appdix; no validation gates were changed.\n\n| Executable | Faktiskt resultat | Giltighet |\n|---|---:|---|\n| Tandvisa kartor | 993 par, 38 280 projected overlapping tooth pairs | Estimated FDI and unchanged source pose |\n| Konservativa minimigapintyg | 38 280/38 280 giltiga intervall | Medianbredd0,266mm; usability gate FAIL |\n| Precisely refined certificates | 440 tandpar, 12 default case; max width0,004998mm | PASS; 981 other cases retain broader certificates |\n| Rasterarea, 0,2→0,1mm | Alla12 actual refinement gates PASS | Projection and proximity bands0,10mm; ingen fysisk area |\n| Negationsfel i klinikerfacit | 121 positiva korsbettsetiketter korrigerade | Original and exact source statements preserved |\n| Crossbit report conflict, test | 30/72→7/72 (41,7%→9,7%) | Corrected text category, not identified inter-assessing noise |\n| Regionalt rapportfynd | ") + str(r6['mixed_anterior_positive_lateral_negative_reports']) + " anterior-positiva/lateral-negativa rapporter | Different regions can be described at the same time without contradiction |\n| Felkontroller | 125/125 explicit negativa laterala utsagor avvisar positiv injektion | Fysisk tanddiagnos fortfarande UNKNOWN |\n\n"
    text += "| Comparison with first readable test report | Exact match | Balanced match | X7 balanced hit | Multiple reports disagree |\n|---|---:|---:|---:|---:|\n"
    labels = {'overbite': "Overbite, R2", 'overjet': "Overjet, R2", 'molar_right': "M1 /Angle right, R2", 'molar_left': "M1 /Angle left, R2"}
    for k in ['overbite', 'overjet', 'molar_right', 'molar_left']:
        f = field[k]
        text += f"| {labels[k]} | {f['first_report']['accuracy']:.3f} | {f['first_report']['balanced_accuracy']:.3f} | {f['x7_first_report']['balanced_accuracy']:.3f} | {f['multi_report_discordance']:.1%} |\n"
    s = r5['scores']
    text += f"| Korsbett, korrigerat facit R5 | {s['corrected_label_model']['accuracy']:.3f} | {s['corrected_label_model']['balanced_accuracy']:.3f} | {s['frozen_X7_model']['balanced_accuracy']:.3f} | {new['discordance']:.1%} |\n"
    text += f"\nR2:s full-bite gate misses: macro balanced hit0,568 mot fryst0,65. R1 kontakt/gap without opposition0,450. The reports have field coverage0,898 and average size1,78 i R2This is not a simultaneous guarantee for the whole bite. X7 is a comparison of answer, no algorithm demand. The simple dental reversed order rule is found {t['named_tooth_recall']:.1%} av namngivna positiva tandobservationer men har bara {t['absence_specificity']:.1%} specificity of the original explicit absence group: FAILUnlisted teeth in positive reports are not established negative.\n\nWhere the discord arises: after negation correction remains35/304 (11,5%) textual conflicts throughout the cross-bite cohort with several readable reports.121 The corrected labels are reading errors, not different clinical perceptions.125 bokstavliga ”no lateral”-reports also describe anterior occurrence; a global label deletes this difference. R6 retains anterior/lateral/ospecificerad region and rejects wrong polarity within the right region. The final syntax binding uses the closest previous modifier, so ”lateral incisors ... anterior crossbite” don't get lateral crossbite.\n\nGeometry's association with real report conflict: for overbited is the uncertainty of the trained geometry model.AUC0,781 (beskrivande patientbootstrap95%0,642–0,904), for overjet0,685 (0,544–0,818). Associationgrinden PASS for these two fields; M1 This shows where geometrically ambiguous model predictions more often coincide with text conflict, **not what causes the disunity of clinics**. Remaining cross-beast conflicts are not causally explained. Examples and regional point candidates: raw/DISAGREEMENT_EXAMPLES.json and raw/MIXED_SCOPE_GEOMETRY_R6.json.\n\nWhat doesn't hold: **877/993** source poses have projected gap<−0,03mm. Negative projection does not prove physical3D penetration; it must not be made into contact force or physical contact area. FDI, cusp/groove, arc shafts, scan recording and mm-accuracy are unvalidated on Bite2Text. The area is a projection; ±0,05mm pose- and ±0,5mm point errors are declared scenarios, not measured spannero safety. A contact graph alone lacks M1-closer edge on112/382 described pages and central incisiveness on:90/193 Opposition solves the information loss but does not validate the points.\n\nAlla grindar bevaras: R1 FAIL (category + too small100mm²-injektion i ett stort kartfall), R2 FAIL (kategori), R3 FAIL (intervallbredd), R4 PASS (12-falls matematik), R5 FAIL (global negation control on five correct mixed region findings), R6 PASS (regionkontroll)The larger area injection is rejected against the same unchanged tolerance, in separate PREREG_CHECK_AREA_CONTROL. No negative gate is readjusted.\n\nX7:s593/198/198-patientdelning The test cohort has already been evaluated in X7/X11 and in previous X21-rounds; this is a frozen descriptive re-evaluation, not an untouched external validation cohort.ID saknas. Parsergranskning av12 source statements are made by the producer. Status **PENDING_INDEPENDENT_REVIEW**.\n\nNext crucial construction: independent blinded FDI-/point marking of the frozen12 the cases, then a loaded registered bite and contact image with calibrated observation teams. Current points and sourcehashes are frozen in FROZEN_MEASUREMENT_PANEL.json; comparison reader rejects injected1mm deviation. The measurements are: NOT_RUN. MATCHED_MEASUREMENT_SPEC.md specify the contract. If the next consumer only needs tighter mesh geometry, R4:s content refinement extended to remaining981 cases; this does not provide any physical information.\n\nResources: map calculation {cost['geometry_preparation_and_query_wall_s']:.1f}s, breda intyg {cost['certificates']['total_wall_s']:.1f}s, exakt12-fall refinement {cost['exact_refinement_R4']['wall_s']:.1f}s inklusive oberoende kontroll. Fit/query, verification and repeated packages are available separately in results.json and raw/RUN_LEDGER.jsonl. Full discovery/code cost and external lab cost UNKNOWN; ingen10x- or cost superior unit claimed. Max measured model-RSS568,5MiB, ≤4 threads, no gpus. {r['large_arrays']['total_bytes'] / 1000000.0:.1f}MB, SHA256 i raw/DATA_ARTIFACT_MANIFEST.json; lane boundary3GB. Ingen komplett ZIP packas upp.\n\nLicens: Bite2Text ZIP saknar README/LICENSE and the authors' public page specifies no explicit data license; exact terms and conditions **UNKNOWN**Only private local research and no raw data published.11The model is trained on Teeth.3DS; [officiella challenge-repot](https://github.com/abenhamadou/3DTeethSeg_MICCAI_Challenges#license) anger CC BY-NC-ND4.0 for data, but the binding to the local snapshot is unclear. No Teeth3DS-mesher used/exported in X21. The other datasets are not used.ID, inga foton eller personuppgifter exporteras.\n\nSource graphs and generated native graphs are unchanged. Matching contact report targets are missing even at the final lookup; GRAPH_FEEDBACK.json proposes limited coverage DENT-VAL-BITE2TEXT-TOOTH-CONTACT-REPORT and berries PENDING_INDEPENDENT_REVIEW. No force target is used to bind another quantity.\n"
    (P / 'README_DEMO.md').write_text(text)
    hand = _release_expand(f"X21-contact-map — sex avslutade konstruktioner, PENDING_INDEPENDENT_REVIEW.\n\n993 maps,38280 per-tooth projected gap enclosures. All complete; @DENTAL_CASE_ID@ explicit empty-source rejection. R4 refines12 cases/440 pairs to maxwidth0.004998232mm; rest retain R3 broad bounds. R1/R2 whole-bite report BA FAIL; R3 useful-width FAIL; R5 global mixed-region injection FAIL preserved; R4 andR6 scopedPASS. README_DEMO.md/results.json contain exact quantities, external referents, gates and limits. Run ./run_all.sh; last verification28 checksPASS and live full-case minima error0.\n\nObservation correction:121 X7 crossbite negation labels were wrong; source/hash/old label retained. Test conflicts30/72→7/72; all304 readable multi-report cases140→35. Five literal no-lateral reports also mention anterior crossbite. R6 separates anterior/lateral/unspecified;125 scoped negative-injection controlsPASS and22 dual-region reports retained. Original R6 clause-last-modifier implementation counted21; final adjacent-per-mention syntax counts22, both raw versions preserved. No anatomical/physical truth inferred.\n\nMain blocker: target FDI/points/pose/physicalcontact absent;877/993 source poses have negative projected gap beyond0.03mm. Angle requires independently identified cusp/groove. Point-proximity/contactgraph cannot determine noncontact anterior relation. Geometry entropy covaries with overbite/overjet text conflict but does not identify cause. Named crossbite rule fails specificity.\n\nNext executable construction: fill frozen12-case independent point/FDI annotation port, compare_measurement.py against frozen original coordinates, no refit. Then loaded registered bite + measured contact image/observation law. These observations not available locally, NOT_RUN. Alternatively only for numerical mesh consumer, extend R4 exact contender refinement to981 remaining maps; do not claim this adds clinical information. Declaration/missing coverage DENT-VAL-BITE2TEXT-TOOTH-CONTACT-REPORT; no dispatch or receipt because matching target absent. GRAPH_FEEDBACK PENDING.\n\nData {r['large_arrays']['total_bytes']} bytes under @DENTAL_WORK_ROOT@/X21, SHA256 manifest {r['large_arrays']['manifest_sha256']}. ≤4 threads,<1GB measuredRSS, noGPU/subagents/wholeZIPextraction/mail/push/clinicalrecommendation or other lane mutations. No own background process remains. Full costUNKNOWN, inheritedX11 fit not treated free. Commands/failures COMMANDS.md, all original failed gates retained.\n")
    (P / 'HANDOFF.md').write_text(hand)
    write(P / 'raw/CODE_SNAPSHOT.json', dict(files=[dict(path=str(p.relative_to(P)), sha256=sha(p)) for p in sorted((P / 'code').glob('*.py'))]))
    state('ROUND_COMPLETE_PARENT_GOAL_OPEN', '993 maps; R4/R6 scopedPASS; broad clinical and physical certification UNKNOWN', 'Independent target tooth/point and registered loaded contact measurements; numerical extension only if required', own_running_jobs=0, completed_rounds=6, verification='28 checks PASS, live minimum parity0mm', graph_review_state='PENDING_INDEPENDENT_REVIEW')
if __name__ == '__main__':
    run()
